#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# Run from the repo root so the library's relative ENV_FILE (.env) and every
# path below resolve there, wherever the wizard was invoked from.
cd "$REPO_ROOT"

# ── Facts this wizard is built on ─────────────────────────────────────────
#
# The live Supabase project. Stages 2 and 8 both refuse to act on the wrong
# one, in opposite directions: stage 2 must touch ONLY this, stage 8 must
# NEVER touch it.
LIVE_SUPABASE_REF="jttycbhcziffiukpcwvd"

# The Manus-era project (ticket 31). Still running, in an organization the
# owner is not an admin of, so it cannot be paused. Rotating its keys is the
# whole of the practical remedy.
MANUS_SUPABASE_REF="mgsbipibzzwrvnseftar"

RENDER_HOST="https://spellcode-backend.onrender.com"
SWEEP_PATH="/api/scheduled/reconcile-payments"
MIGRATION="docs/supabase_payment_reconciliation_migration.sql"
ROLLBACK="docs/supabase_payment_reconciliation_rollback.sql"
WORKFLOW="reconcile-payments.yml"

# ── Resume state ──────────────────────────────────────────────────────────
#
# Both earlier wizards in this directory have NO resume state, and that is
# the single fault that cost the most: re-running finish-switch-wizard.sh to
# reach a later stage walks back through its stage 7, which cannot succeed
# and does not notice, so the run reads clean while the work stays open.
#
# This wizard resumes two ways, and prefers the first:
#
#   1. By PROBE, wherever reality can be read - the reconciliation_error
#      column either exists or it does not; the endpoint answers 503 or 401.
#      This repo's own conventions say prefer a probe to the prose, and a
#      probe cannot go stale the way a checkbox in a file can.
#   2. By STATE FILE, only for the stages nothing can probe - a key rotated
#      in a dashboard, a checkout a human watched succeed.
#
# The state file holds stage names and timestamps. No values, no secrets.
STATE_FILE="docs/domain-model-alignment/.operator-remainder.state"

mark_done() { printf '%s\t%s\n' "$1" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >> "$STATE_FILE"; }
is_done()   { [[ -f "$STATE_FILE" ]] && grep -qE "^${1}\b" "$STATE_FILE"; }

# offer_skip NAME "what it was" returns success when the human wants to skip
# a stage the state file says is already done. It always OFFERS rather than
# skipping silently: a wizard that decides for you is how a stage gets
# quietly walked past.
offer_skip() {
  local name="$1" what="$2" when
  is_done "$name" || return 1
  when=$(grep -E "^${name}\b" "$STATE_FILE" | tail -n1 | cut -f2)
  note "This stage was recorded done at ${when}: $what"
  confirm "Skip it?" && return 0
  return 1
}

# ── Reading and probing ───────────────────────────────────────────────────

# read_env KEY prints KEY's value from .env.
read_env() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  line="${line#*=}"; line="${line%\"}"; line="${line#\"}"
  printf '%s' "$line"
}

# postgrest PATH runs a read-only PostgREST query with the service-role key.
# Read-only by construction: this wizard sends no method but GET here.
postgrest() {
  local url key
  url=$(read_env SUPABASE_URL || true)
  key=$(read_env SUPABASE_SERVICE_ROLE_KEY || true)
  [[ -n "$url" && -n "$key" ]] || return 1
  curl -fsS --max-time 30 -H "apikey: $key" -H "Authorization: Bearer $key" \
    "${url%/}/rest/v1/$1"
}

# sweep_code prints the HTTP status of an unauthenticated POST to the sweep
# endpoint. It carries no secret, so it can never start a run:
#
#   503  the endpoint is live and SCHEDULED_TASKS_SECRET is NOT set on Render
#   401  the endpoint is live and the secret IS set
#   200  something is very wrong - it should never authenticate an empty secret
#   404 / 000  the endpoint is not deployed, or the host is unreachable
#
# reconcilePayments.ts:181 refuses before it authenticates when the variable
# is unset, which is what makes 503 and 401 distinguishable at all. That is
# deliberately unlike stage 8 of the switch, where an empty webhook-events
# array could not tell "never set" from "set, nothing fired yet".
sweep_code() {
  curl -s -o /dev/null -w '%{http_code}' --max-time 120 \
    -X POST "${RENDER_HOST}${SWEEP_PATH}" 2>/dev/null || printf '000'
}

# column_exists TABLE COLUMN: success when PostgREST can select the column.
# A missing column answers 42703 and curl -f makes that a failure.
column_exists() { postgrest "${1}?select=${2}&limit=1" >/dev/null 2>&1; }

# copy_to_clipboard VALUE puts a value on the clipboard where possible, so a
# secret gets into a dashboard without being printed into terminal scrollback.
copy_to_clipboard() {
  if   command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe && return 0
  elif command -v clip     >/dev/null 2>&1; then printf '%s' "$1" | clip     && return 0
  elif command -v pbcopy   >/dev/null 2>&1; then printf '%s' "$1" | pbcopy   && return 0
  elif command -v xclip    >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard && return 0
  fi
  return 1
}

banner "SpellCode: the operator remainder"

