esac

if column_exists payment_transactions reconciliation_error; then
  note "  migration      : reconciliation_error present - already run"
else
  note "  migration      : reconciliation_error absent, or .env could not read"
fi
printf '\n'
pause "Ready?"

# -- 2 ---------------------------------------------------------------------
stage "Ticket 35: run the reconciliation migration"
say "This adds payment_transactions.reconciliation_error, which is how a"
say "payment the sweep cannot resolve becomes visible to a human."
