  step "Open the spellcode-backend service."
  step "Environment, then Add Environment Variable."
  step "Key: SCHEDULED_TASKS_SECRET   Value: paste from the clipboard."
  step "Save. Render will redeploy - that restarts production briefly."
  printf '\n'
  warn "Saving here restarts the live backend."
  if confirm "Saved, and the redeploy has finished?"; then
    printf '\n'
    say "Checking that the endpoint changed its answer:"
    FLIPPED=""
    for _attempt in 1 2 3 4 5 6; do
      CODE=$(sweep_code)
      note "  probe: $CODE"
      if [[ "$CODE" == "401" ]]; then FLIPPED="yes"; break; fi
      note "  not yet - waiting 20s (a cold Render start can exceed 45s)"
      sleep 20
    done
    if [[ -n "$FLIPPED" ]]; then
      printf '  %s✓ verified%s 503 became 401: Render holds the secret\n' "$GREEN" "$RESET"
      mark_done render_secret
    else
      warn "Still not 401. The variable may not have saved, or the redeploy"
      note "  is not finished. Re-run this wizard later; stage 1 will tell you."
