  printf '\n'
  say "Wake Render first. A cold start exceeds 45 seconds and Paystack's"
  say "webhook timeout is 30, so a sleeping instance loses the delivery."
  open_url "$RENDER_HOST/api/mobile/config"
  pause "Press Enter once that returned JSON."

  PROD_ORIGIN=$(read_env VERCEL_ORIGIN || true)
  PROD_ORIGIN="${PROD_ORIGIN:-https://spellcode-by-aceify-two.vercel.app}"
  printf '\n'
  open_url "$PROD_ORIGIN/auth"
  step "Sign up as a NEW test Learner and confirm the email."
  step "Then go to Access and start a Full Access one-time checkout."
  printf '\n'
  say "Pay with a Paystack test card. Do not guess the number - the current"
  say "test cards are listed here:"
  open_url "https://paystack.com/docs/payments/test-payments/"
  printf '\n'
  warn "Confirm you are on the right Paystack business before reading any"
  note "  dashboard: the correct one is whichever lists the transaction"
  note "  spellcode-963cdeab-a97c-40e4-8b2f-16a20889c376. Dashboard URLs"
  note "  carry no business identifier, so no link can target one (ticket 30)."
  printf '\n'
  if confirm "Did the checkout complete and Full Access appear?"; then
    printf '\n'
    say "Reading the database rather than trusting the page:"
    postgrest "payment_transactions?select=reference,status,created_at&order=created_at.desc&limit=3" || warn "could not read payment_transactions"
    printf '\n'
    postgrest "subscriptions?select=status,installments_paid,total_installments,created_at&order=created_at.desc&limit=3" || warn "could not read subscriptions"
    printf '\n'
    say "Expect the newest payment at status success, and a subscription at"
    say "active. Under ticket 34 the subscription is written at VERIFIED"
    say "payment, not at checkout - so there should be no pending row at all."
    printf '\n'
    if confirm "Does that match?"; then
      mark_done checkout34
      printf '  %s✓ ticket 34 has its browser verification%s\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("ticket 34: the post-34 checkout did not settle as expected - investigate")
    fi
  else
    SKIPPED+=("ticket 34: a test-mode checkout after ticket 34 landed")
  fi
  printf '\n'
  warn "This grants Full Access on a test card, in production."
  note "  Exclude it from any revenue figure by user_id, by hand:"
  note "  payment_transactions has no mode column, so nothing distinguishes"
  note "  it from a real purchase and adminLearnerBilling will count it."
fi
printf '\n'
pause "Continue."

# -- 8 ---------------------------------------------------------------------
stage "Ticket 31: rotate the Manus project's keys"
say "The Manus-era Supabase project is still running, in an organization the"
say "owner is not an admin of. It holds no third-party data - ten accounts,"
say "all the owner's or the one collaborator - so there is no retention"
say "deadline and nobody to notify."
printf '\n'
say "Rotating its keys is the whole of the practical remedy. Nothing in this"
say "repository points at that project, so rotation breaks nothing."
printf '\n'

if offer_skip rotate31 "the Manus project's keys were rotated"; then
  note "Skipped."
elif [[ "$MANUS_SUPABASE_REF" == "$LIVE_SUPABASE_REF" ]]; then
  warn "Refusing to act: the Manus ref matches the live ref. Someone has"
  note "  edited this wizard wrongly. Rotating the live project's keys would"
  note "  break Render, Vercel and every signed-in Learner at once."
  SKIPPED+=("ticket 31: refused to act, ref collision in the wizard")
else
  note "Acting on $MANUS_SUPABASE_REF. The live project is $LIVE_SUPABASE_REF"
  note "  and this stage must never touch it."
  printf '\n'
  open_url "https://supabase.com/dashboard/project/${MANUS_SUPABASE_REF}/settings/api"
  step "Check the ref in the URL reads ${MANUS_SUPABASE_REF} before anything else."
  step "Rotate the service_role key, and the anon key."
  printf '\n'
  note "Rotation may be an admin action you do not have. If the control is"
  note "  absent or refuses, that is itself the answer and worth recording."
  printf '\n'
  if confirm "Were you able to rotate them?"; then
    mark_done rotate31
    note "Recorded. Getting admin rights to pause or delete the project is"
    note "  housekeeping after this, not urgent."
  else
    SKIPPED+=("ticket 31: rotate ${MANUS_SUPABASE_REF} keys - blocked, pursue org admin rights")
    warn "Noted. Ticket 31 asks who administers that organization; the answer"
    note "  decides whether this is a conversation or an escalation."
  fi
  printf '\n'
  warn "Do NOT try to pause or delete that project here."
  note "  It is switch stage 8, it needs admin rights the owner lacks, and"
  note "  attempting it is how an hour disappears. Rotation is the win."
  printf '\n'
  note "Separately still open: ticket 26's rotation question, about whether"
  note "  the DELETED Vercel project held the service-role key for the LIVE"
  note "  project. Two different keys - do not conflate them. Rotating that"
  note "  one means updating Render's environment in the same sitting."
fi
printf '\n'
pause "Continue."

# -- 9 ---------------------------------------------------------------------
stage "Ticket 32: the cutover, reported and NOT performed"
say "This stage reads state and refuses to change it. Read why before"
say "deciding to override that."
printf '\n'
say "Current plan rows, read from the live database:"
printf '\n'
postgrest "plans?select=code,interval,is_active,paystack_plan_code&order=code" || warn "could not read plans"
printf '\n'
say "The cutover is THREE coupled changes, not two (ADR 0004):"
note "  1. Render's PAYSTACK_SECRET_KEY and the client's public key to live"
note "  2. The live-mode Webhook URL set - done 2026-09-28"
note "  3. plans.paystack_plan_code patched to the LIVE plan codes, via"
note "     billing.updatePlan (an adminProcedure, not SQL by hand)"
printf '\n'
warn "Move 1 and 2 without 3 and installment checkouts break at paystack.ts:46."
warn "Move 3 early and test-mode installment work breaks instead."
printf '\n'
say "Worse than either: a Paystack plan object exists in exactly ONE mode, so"
say "the same plan has different PLN_ codes in test and live. Whichever mode's"
say "code is stored is the mode that works, and the other fails SILENTLY - a"
say "recurring charge succeeds, the webhook arrives, verifies, finds no plan"
say "and is dropped without a record. Money moves and the application says"
say "nothing. That is ticket 28's shape for the third time."
printf '\n'
note "Nothing can hit that today: both installment plans are is_active false,"
note "  so they are refused at paystack.ts:45 before :46 is reached, and the"
note "  one-time plan never sends a plan code at all. The hazard arrives the"
note "  moment installments are switched on."
printf '\n'
warn "This wizard will not perform the cutover, and that is deliberate."
note "  Three launch gates still sit in front of it: a live-money Paystack"
note "  test, a Render instance that does not sleep, and custom SMTP for"
note "  Auth email. Cutover also wants all three changes in one sitting,"
note "  which is a different wizard written when those gates are clear."
printf '\n'
SKIPPED+=("ticket 32: the three-part cutover - deliberately not attempted here")
pause "Continue to the summary."

finish

printf '  %s%sWhere this leaves the effort%s\n' "$BOLD" "$BLUE" "$RESET"
note "Resume state is in $STATE_FILE. Re-running this wizard re-probes"
note "  everything it can and offers to skip the rest - unlike the two older"
note "  wizards beside it, which must not be re-run at all."
printf '\n'
note "Update docs/domain-model-alignment/handoff.md with whatever changed."
